/**
 * Transactional template — attendee ticket.
 *
 * Per §16.3 `attendee.ticket` (email with PDF attached). Sent to
 * EACH ATTENDEE (one email per attendee row). The accompanying PDF
 * is generated by `services/tickets/render-ticket-pdf.ts` and
 * attached by the delivery worker via the SES raw-MIME path.
 *
 * For MVP, the attendee's `attendee_email` falls back to the buyer's
 * email when not set (see `services/attendees/generate.ts`); per-
 * attendee email capture is Phase 2 form-builder scope.
 *
 * Bilingual per Decision O.2 / §1.3 R12.
 */

import type { LocaleCode } from '../../../services/notifications/locale.js'

export interface AttendeeTicketVars {
  attendeeName: string
  eventTitle: string
  eventStartsAt: Date
  eventTimezone: string
  venue: string
  tierName: string
  /** Plain link to the same PDF, useful when the attachment fails to render. */
  ticketViewUrl?: string
  locale: LocaleCode
}

export interface RenderedEmail {
  templateId: string
  subject: string
  text: string
  html: string
}

function formatDateTime(date: Date, timezone: string, locale: LocaleCode): string {
  const lang = locale === 'bn' ? 'bn-BD' : 'en-GB'
  return new Intl.DateTimeFormat(lang, {
    timeZone: timezone,
    weekday: 'long',
    year: 'numeric',
    month: 'long',
    day: 'numeric',
    hour: '2-digit',
    minute: '2-digit',
  }).format(date)
}

export function renderAttendeeTicket(vars: AttendeeTicketVars): RenderedEmail {
  const when = formatDateTime(vars.eventStartsAt, vars.eventTimezone, vars.locale)

  const subject =
    vars.locale === 'bn' ? `আপনার টিকিট — ${vars.eventTitle}` : `Your ticket — ${vars.eventTitle}`

  const text =
    vars.locale === 'bn'
      ? [
          `নমস্কার ${vars.attendeeName},`,
          ``,
          `${vars.eventTitle} এর জন্য আপনার টিকিট সংযুক্ত করা হলো (PDF)।`,
          ``,
          `ইভেন্ট: ${vars.eventTitle}`,
          `কখন: ${when} (${vars.eventTimezone})`,
          `কোথায়: ${vars.venue}`,
          `টিকিট ধরন: ${vars.tierName}`,
          ``,
          `প্রবেশের সময় QR কোড স্ক্যান করানো হবে। PDF টি প্রিন্ট করুন বা ফোনে রাখুন।`,
          `এই টিকিট অন্যকে দেখাবেন না — QR এর মাধ্যমে যে কেউ প্রবেশ করতে পারবে।`,
          ``,
          `প্রশ্ন থাকলে support@eventpulse.com.bd তে যোগাযোগ করুন।`,
          ``,
          `— Event Pulse`,
          `https://eventpulse.com.bd`,
        ].join('\n')
      : [
          `Hi ${vars.attendeeName},`,
          ``,
          `Your ticket for ${vars.eventTitle} is attached as a PDF.`,
          ``,
          `Event: ${vars.eventTitle}`,
          `When: ${when} (${vars.eventTimezone})`,
          `Where: ${vars.venue}`,
          `Ticket type: ${vars.tierName}`,
          ``,
          `Your QR code will be scanned at entry. Print the PDF or keep it on your phone.`,
          `Do NOT share this ticket — anyone with the QR can enter.`,
          ``,
          `Questions? Reply to support@eventpulse.com.bd.`,
          ``,
          `— Event Pulse`,
          `https://eventpulse.com.bd`,
        ].join('\n')

  const heading = vars.locale === 'bn' ? 'আপনার টিকিট' : 'Your ticket'
  const greeting =
    vars.locale === 'bn' ? `নমস্কার ${vars.attendeeName},` : `Hi ${vars.attendeeName},`
  const intro =
    vars.locale === 'bn'
      ? `${vars.eventTitle} এর জন্য আপনার টিকিট সংযুক্ত করা হলো (PDF)।`
      : `Your ticket for ${vars.eventTitle} is attached as a PDF.`
  const warning =
    vars.locale === 'bn'
      ? `এই টিকিট অন্যকে দেখাবেন না — QR এর মাধ্যমে যে কেউ প্রবেশ করতে পারবে।`
      : `Do NOT share this ticket — anyone with the QR can enter.`
  const labels =
    vars.locale === 'bn'
      ? { event: 'ইভেন্ট', when: 'কখন', where: 'কোথায়', tier: 'টিকিট ধরন' }
      : { event: 'Event', when: 'When', where: 'Where', tier: 'Ticket type' }

  const html = `<!doctype html>
<html><head><meta charset="utf-8"><title>${escapeHtml(subject)}</title></head>
<body style="font-family:system-ui,-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;background:#f6f5fb;margin:0;padding:24px;color:#2a2a36">
  <table role="presentation" cellpadding="0" cellspacing="0" border="0" width="100%" style="max-width:560px;margin:0 auto;background:#ffffff;border-radius:16px;padding:32px;box-shadow:0 4px 24px rgba(20,18,60,0.06)">
    <tr><td>
      <h1 style="font-size:20px;margin:0 0 16px;color:#0b0b14">${heading}</h1>
      <p style="margin:0 0 16px;line-height:1.6">${greeting}</p>
      <p style="margin:0 0 24px;line-height:1.6">${intro}</p>

      <table cellpadding="0" cellspacing="0" border="0" width="100%" style="margin:0 0 24px">
        <tr><td style="padding:8px 0;color:#6b6b7a;width:40%">${labels.event}</td><td style="padding:8px 0;color:#0b0b14"><strong>${escapeHtml(vars.eventTitle)}</strong></td></tr>
        <tr><td style="padding:8px 0;color:#6b6b7a">${labels.when}</td><td style="padding:8px 0;color:#0b0b14">${escapeHtml(when)} (${escapeHtml(vars.eventTimezone)})</td></tr>
        <tr><td style="padding:8px 0;color:#6b6b7a">${labels.where}</td><td style="padding:8px 0;color:#0b0b14">${escapeHtml(vars.venue)}</td></tr>
        <tr><td style="padding:8px 0;color:#6b6b7a">${labels.tier}</td><td style="padding:8px 0;color:#0b0b14">${escapeHtml(vars.tierName)}</td></tr>
      </table>

      <p style="margin:0 0 16px;line-height:1.6;color:#ff4d7e;font-weight:600">${warning}</p>

      <hr style="border:none;border-top:1px solid #e4e2ee;margin:24px 0">
      <p style="font-size:12px;color:#9b9bb0;margin:0">— Event Pulse · <a href="https://eventpulse.com.bd" style="color:#4a5bff">eventpulse.com.bd</a></p>
    </td></tr>
  </table>
</body></html>`

  return { templateId: 'attendee_ticket', subject, text, html }
}

function escapeHtml(s: string): string {
  return s.replace(/[&<>"']/g, (c) =>
    c === '&' ? '&amp;' : c === '<' ? '&lt;' : c === '>' ? '&gt;' : c === '"' ? '&quot;' : '&#39;',
  )
}
